sysevent_in_email_action.script:
(function(process, email, email_action, event) { 
	// Get the incident record based on the sys_id in the email instance    
    var incidentGR = new GlideRecord('incident');
    if (incidentGR.get(email.instance.sys_id)) { // Reopen the incident      
        incidentGR.state = 2; // Set the state to "Reopened" (adjust the state value based on your workflow)    
        // Add the email body text as a work note      
        incidentGR.work_notes = "Customer response via email: \n" + email.body_text;
        // Update the incident record        
        incidentGR.update(); // Log the action for debugging purposes (optional)   
        gs.log("Incident " + incidentGR.number + " has been reopened based on customer email response.");
    }

	else {
		var incidentSysId = email.body.match(/sys_id=(\w+)/)[1];
        if (incidentGR.get(incidentSysId)) {
        incidentGR.state = 2; // In Arbeit
		incidentGR.work_notes = "Customer response via email: \n" + email.body_text;
        incidentGR.update();
		gs.log("Incident " + incidentGR.number + " has been reopened based on customer email response.");
    }
	}



})(current, email, email_action, event);
